#include "support/journal_worker_peer.h"
static void jlQueued(bool PoolCancel)
{
    jwdrive D={0};jpfile F=jwFile(&D);xtaskpool* P=jwPool(1);jwblock B={0};xfuture* Block=xrtTaskSubmit(P,jwBlock,&B,NULL);testRequire(Block!=NULL,"host blocker");jwAwait(&B.Started);xmqttjournalworkerconfig C;xmqttJournalWorkerConfigInit(&C);C.MaxObjects=C.MaxRequests=4;xmqttjournalworker* W=jwCreate(F,&D,P,&C);
    xfuture *A=NULL,*Expired=NULL,*Kept=NULL;testRequire(xmqttJournalWorkerAppendAsync(W,XRT_BYTES_LITERAL("cancel"),10000,&A)==XMQTT_JWORK_ACCEPTED&&xmqttJournalWorkerAppendAsync(W,XRT_BYTES_LITERAL("expired"),1,&Expired)==XMQTT_JWORK_ACCEPTED&&xmqttJournalWorkerAppendAsync(W,XRT_BYTES_LITERAL("keep"),10000,&Kept)==XMQTT_JWORK_ACCEPTED,"three immutable queued admissions");xcancel* Token=xrtFutureCancelToken(A);testRequire(Token&&xrtCancelRequest(Token)&&xrtFutureState(A)==XFUTURE_PENDING,"raw token cancellation does not fabricate result");xrtCancelDestroy(Token);xrtSleep(5);
    if(PoolCancel)testRequire(xrtTaskPoolCancel(P),"cancel queued native pump before Proc");else xrtAtomic32Store(&B.Released,1,XMEMORY_RELEASE);
    const xmqttcommitresult *RA=jwOutcome(A),*RE=jwOutcome(Expired),*RK=jwOutcome(Kept);testRequire(RA->Status==(PoolCancel?XMQTT_COMMIT_INITIALIZATION:XMQTT_COMMIT_CANCELLED)&&RE->Status==(PoolCancel?XMQTT_COMMIT_INITIALIZATION:XMQTT_COMMIT_TIMEOUT)&&RK->Status==(PoolCancel?XMQTT_COMMIT_INITIALIZATION:XMQTT_COMMIT_OK),"queued cancel/expiry or native task Drop typed outcomes");
    testRequire(!RA->AppendCalled&&!RE->AppendCalled&&RA->Effect==XMQTT_JOURNAL_NOT_COMMITTED&&RE->Effect==XMQTT_JOURNAL_NOT_COMMITTED&&RK->Sequence==(PoolCancel?0u:1u),"no IO for pre-start cancellation/deadline/native skip");testRequire(xmqttJournalWorkerDestroy(W),"skipped native task still returns physical ownership");jwPoolDone(P);xrtFutureDestroy(Block);jpFileClose(F);xrtFutureDestroy(A);xrtFutureDestroy(Expired);xrtFutureDestroy(Kept);
}
static void jlActive(unsigned Stop)
{
    jwdrive D={0};jpfile F=jwFile(&D);xtaskpool* P=jwPool(2);xmqttjournalworkerconfig C;xmqttJournalWorkerConfigInit(&C);xmqttjournalworker* W=jwCreate(F,&D,P,&C);D.Hold=4;D.CheckWorker=true;xfuture *A=NULL,*B=NULL;
    testRequire(xmqttJournalWorkerAppendAsync(W,XRT_BYTES_LITERAL("active"),Stop==1?1000:10000,&A)==XMQTT_JWORK_ACCEPTED,"active first commit");jwAwait(&D.Entered);testRequire(xmqttJournalWorkerAppendAsync(W,XRT_BYTES_LITERAL("queued"),10000,&B)==XMQTT_JWORK_ACCEPTED,"queued during physical native append");
    if(Stop==0)testRequire(xrtFutureCancel(A),"cancel running append");else if(Stop==1)xrtSleep(1100);else testRequire(xmqttJournalWorkerClose(W),"close during append");
    testRequire(xrtFutureWaitFor(A,1)==XWAIT_TIMEOUT&&jwSnapshot(W).Busy&&jwSnapshot(W).Requests==2,"logical wait timeout cannot discard active IO credits");
    if(Stop==2)testRequire(xmqttJournalWorkerWaitFor(W,1)==XWAIT_TIMEOUT,"close waits for native IO");
    xrtAtomic32Store(&D.Release,1,XMEMORY_RELEASE);
    const xmqttcommitresult* R=jwOutcome(A);testRequire(R->Effect==XMQTT_JOURNAL_COMMITTED&&R->Sequence==1&&R->AppendCalled&&R->Status==(Stop==0?XMQTT_COMMIT_CANCELLED:Stop==1?XMQTT_COMMIT_TIMEOUT:XMQTT_COMMIT_CLOSED),"late cancellation/timeout/close preserves actual COMMITTED fact");
    R=jwOutcome(B);testRequire(R->Status==(Stop==2?XMQTT_COMMIT_CLOSED:XMQTT_COMMIT_OK)&&R->Sequence==(Stop==2?0u:2u),"only pre-start queued Close prevents IO");testRequire(xmqttJournalWorkerDestroy(W)&&D.Checked>=7,"backend reentry and host-thread proof");jwPoolDone(P);jpFileClose(F);xrtFutureDestroy(A);xrtFutureDestroy(B);
}
typedef struct jlwatch {xmqttjournalworker* W;xatomic32 Entered,Release,Released;xmqttjournaladmission Admission;xfuture* Extra;} jlwatch;
static void jlNotify(ptr Data)
{jlwatch* X=Data;testRequire(jwSnapshot(X->W).Objects==1&&xmqttJournalWorkerWaitFor(X->W,0)==XWAIT_ERROR&&!xmqttJournalWorkerDestroy(X->W),"completion reentry cannot wait/destroy own physical tail");xrtClearError();X->Admission=xmqttJournalWorkerAppendAsync(X->W,XRT_BYTES_LITERAL("next"),1000,&X->Extra);xrtAtomic32Store(&X->Entered,1,XMEMORY_RELEASE);jwAwait(&X->Release);}
static void jlRelease(ptr Data){jlwatch* X=Data;xrtAtomic32Store(&X->Released,1,XMEMORY_RELEASE);}
static void jlWatch(void)
{
    jwdrive D={0};jpfile F=jwFile(&D);xtaskpool* P=jwPool(1);jwblock B={0};xfuture* Block=xrtTaskSubmit(P,jwBlock,&B,NULL);jwAwait(&B.Started);xmqttjournalworkerconfig C;xmqttJournalWorkerConfigInit(&C);C.MaxObjects=1;xmqttjournalworker* W=jwCreate(F,&D,P,&C);xfuture* A=NULL;testRequire(xmqttJournalWorkerAppendAsync(W,XRT_BYTES_LITERAL("held"),10000,&A)==XMQTT_JWORK_ACCEPTED,"watch source queued");jlwatch X={.W=W};xfuturewatch Watch;testRequire(xrtFutureWatchInit(&Watch,jlNotify,jlRelease,&X)&&xrtFutureWatchAdd(A,&Watch)==XFUTURE_WATCH_PENDING,"actual synchronous completion Watch");xrtAtomic32Store(&B.Released,1,XMEMORY_RELEASE);jwAwait(&X.Entered);testRequire(X.Admission==XMQTT_JWORK_OVERLOADED&&!X.Extra&&xrtFutureDone(A),"completed but callback-held result still consumes exact object cap");testRequire(xmqttJournalWorkerClose(W)&&xmqttJournalWorkerWaitFor(W,1)==XWAIT_TIMEOUT,"logical completion cannot hide callback/native task tail");xrtAtomic32Store(&X.Release,1,XMEMORY_RELEASE);jwAwait(&X.Released);testRequire(xmqttJournalWorkerWaitFor(W,10000)==XWAIT_OK&&jwSnapshot(W).Objects==1&&xmqttJournalWorkerDestroy(W),"result independent from native retirement");jwPoolDone(P);jpFileClose(F);testRequire(jwOutcome(A)->Sequence==1,"retained result outlives physical owners");xrtFutureDestroy(A);xrtFutureDestroy(Block);
}
typedef struct jlturn {xmqttjournalworker* W;xfuture *Second,*Third;xfuturewatch Next;xatomic32 Done;xmqttjournaladmission Last;} jlturn;
static void jlTurnSecond(ptr Data)
{jlturn* X=Data;X->Last=xmqttJournalWorkerAppendAsync(X->W,XRT_BYTES_LITERAL("third"),10000,&X->Third);xrtAtomic32Store(&X->Done,1,XMEMORY_RELEASE);}
static void jlTurnFirst(ptr Data)
{jlturn* X=Data;testRequire(xmqttJournalWorkerAppendAsync(X->W,XRT_BYTES_LITERAL("second"),10000,&X->Second)==XMQTT_JWORK_ACCEPTED,"second admission replenishes same pump after first completion");testRequire(xrtFutureWatchInit(&X->Next,jlTurnSecond,NULL,X)&&xrtFutureWatchAdd(X->Second,&X->Next)==XFUTURE_WATCH_PENDING,"next turn callback registered before physical second append");}
static void jlTurns(void)
{
    jwdrive A={0},B={0};jpfile FA=jwFile(&A),FB=jwFile(&B);xtaskpool* P=jwPool(1);xmqttjournalworkerconfig C;xmqttJournalWorkerConfigInit(&C);C.WorkTransactions=2;xmqttjournalworker* WA=jwCreate(FA,&A,P,&C);xmqttjournalworker* WB=jwCreate(FB,&B,P,&C);jwblock Block={0};xfuture* Holding=xrtTaskSubmit(P,jwBlock,&Block,NULL);jwAwait(&Block.Started);
    jlturn X={.W=WA};xfuture *First=NULL,*Other=NULL;testRequire(xmqttJournalWorkerAppendAsync(WA,XRT_BYTES_LITERAL("first"),10000,&First)==XMQTT_JWORK_ACCEPTED,"first owner pump queued");xfuturewatch Watch;testRequire(xrtFutureWatchInit(&Watch,jlTurnFirst,NULL,&X)&&xrtFutureWatchAdd(First,&Watch)==XFUTURE_WATCH_PENDING,"actual hot-owner replenishment watch");testRequire(xmqttJournalWorkerAppendAsync(WB,XRT_BYTES_LITERAL("other"),10000,&Other)==XMQTT_JWORK_ACCEPTED,"second owner queued on same one-thread host");xrtAtomic32Store(&Block.Released,1,XMEMORY_RELEASE);
    testRequire(jwOutcome(Other)->Effect==XMQTT_JOURNAL_COMMITTED,"second journal progresses after finite hot-owner turn");jwAwait(&X.Done);testRequire(X.Last==XMQTT_JWORK_OVERLOADED&&!X.Third&&jwOutcome(X.Second)->Sequence==2,"turn budget counts lifetime admissions rather than instantaneous queue depth");
    double End=xrtTimer()+10;xmqttjournaladmission R;do{R=xmqttJournalWorkerAppendAsync(WA,XRT_BYTES_LITERAL("third"),10000,&X.Third);if(R==XMQTT_JWORK_OVERLOADED)xrtSleep(1);testRequire(xrtTimer()<End,"next host-tail turn deadline");}while(R==XMQTT_JWORK_OVERLOADED);testRequire(R==XMQTT_JWORK_ACCEPTED&&jwOutcome(X.Third)->Sequence==3,"new pump resets admission window and preserves sequence");
    testRequire(xmqttJournalWorkerDestroy(WA)&&xmqttJournalWorkerDestroy(WB),"both journals physically retire");jwPoolDone(P);jpFileClose(FA);jpFileClose(FB);xrtFutureDestroy(Holding);xrtFutureDestroy(First);xrtFutureDestroy(Other);xrtFutureDestroy(X.Second);xrtFutureDestroy(X.Third);
}
int main(void){jlQueued(false);jlQueued(true);for(unsigned I=0;I<3;++I)jlActive(I);jlWatch();jlTurns();puts("[PASS] queued/raw cancellation,expiry,native task cancellation,late COMMITTED outcomes,reentrant Watch and true physical retirement");return 0;}
